window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-91b93f80faada818"]={"versions": [{"id": "FIG-91b93f80faada818", "releases": ["R17-10_R1.2.0", "R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Block- und Deploymentdiagramm für den Testaufbau (Test Setup) zur Verifikation von Logging und Tracing (LT) in einer verteilten AUTOSAR Adaptive Platform Systemumgebung. Dargestellt ist die physische und logische Aufteilung auf zwei Steuergeräte (ECU1, ECU2) sowie einen externen Testautomatisierungsknoten (Jenkins).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das System umfasst drei Hauptknoten:</p>\n<ul class=\"fig-list\"><li><strong>ECU1</strong>: Hardware „Intel MinnowBoard“, Betriebssystem „Linux with Real-time Patches“. Darauf läuft ein Software-Stack bestehend aus „POSIX libs (libc, ...)“, den Middleware-/Kommunikationsbibliotheken „vSomeIP“ und „Genivi-dlt“, der Laufzeitumgebungsschicht „ARA“ (AUTOSAR Runtime for Adaptive Applications) sowie der Applikation „Video Data“.\n</li><li><strong>ECU2</strong>: Hardware „Renesas R-CAR H3 ULCB“, Betriebssystem „Linux with Real-time Patches“. Der Software-Stack umfasst identisch „POSIX libs (libc, ...)“, „vSomeIP“, „Genivi-dlt“, „ARA“ und die Zielanwendung „System Test Applications“.\n</li><li><strong>Jenkins</strong>: Hardware „PC“, Betriebssystem „Linux with Real-time Patches“. Darauf läuft ein „Jenkins“-Ausführungsblock, der den „LT Tester“ ansteuert bzw. ausführt.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Verbindungspfade (gestrichelte rote Linien):</p>\n<ul class=\"fig-list\"><li>Vertikaler Kommunikationspfad für Logging/Tracing: Von „Video Data“ (ECU1) und „System Test Applications“ (ECU2) über „Genivi-dlt“, OS und Hardware zu einer gemeinsamen externen Diagnoselinie, die zum „LT Tester“ auf dem Jenkins-Host führt.\n</li><li>Vertikaler Kommunikationspfad für SOME/IP-Datenaustausch: Von „Video Data“ (ECU1) über „vSomeIP“, OS und Hardware zur Hardware von ECU2, von dort über OS und „vSomeIP“ nach oben zu „ARA“ und mit Pfeilspitze in „System Test Applications“.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>SOME/IP-Kommunikation</strong>: ECU1 sendet Datenströme (Video Data) über SOME/IP („vSomeIP“) via Ethernet an ECU2. Das Signal verläuft gerichtet von ECU1 über die Hardware-Verbindung zur ECU2, durchläuft den Stack aufwärts und wird in „System Test Applications“ eingespeist (Pfeilspitze an System Test Applications).\n</li><li><strong>Log-/Trace-Erfassung</strong>: Beide ECUs generieren Log- und Trace-Ereignisse über die DLT-Infrastruktur („Genivi-dlt“). Diese Nachrichten werden über separate Pfade an den Jenkins-Knoten übertragen und gerichtet an den „LT Tester“ übergeben (Pfeilspitzen am LT Tester für beide Ströme).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient als Referenzaufbau für Systemintegrationstests von Logging and Tracing (ARA Diagnostic Log and Trace). Es spezifiziert die Trennung von Teststimulus-/Nutzdatenkommunikation (via SOME/IP zwischen den ECUs) und Logging-Protokoll-Rückkanal (via DLT zum Testrechner/Jenkins). Für Implementierer und Testingenieure definiert es die erforderlichen Hardware-Plattformen, Betriebssystemvoraussetzungen (Echtzeit-Linux) und Open-Source-Basiskomponenten (vSomeIP, Genivi-dlt).</p>"}, {"id": "FIG-c4f501c01aa30c48", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Block- und Deploymentdiagramm für den Testaufbau (Test Setup) zur Verifikation von Logging und Tracing (LT) in einer verteilten AUTOSAR Adaptive Platform Systemumgebung. Dargestellt ist die physische und logische Aufteilung auf zwei Steuergeräte (ECU1, ECU2) sowie einen externen Testautomatisierungsknoten (Jenkins).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das System umfasst drei Hauptknoten:</p>\n<ul class=\"fig-list\"><li><strong>ECU1</strong>: Hardware „Intel MinnowBoard“, Betriebssystem „Linux with Real-time Patches“. Software-Stack bestehend aus „POXIS libs (libc, ...)“, „vSomeIP“, „Ginivi-dlt“, „ARA“ sowie der Applikation „Video Data“.\n</li><li><strong>ECU2</strong>: Hardware „Renesas R-CAR H3 ULCB“, Betriebssystem „Linux with Real-time Patches“. Software-Stack bestehend aus „POXIS libs (libc, ...)“, „vSomeIP“, „Ginivi-dlt“, „ARA“ und der Anwendung „System Test Applications“.\n</li><li><strong>Jenkins</strong>: Hardware „PC“, Betriebssystem „Linux“. Darauf läuft ein „Jenkins“-Block, der den „LT Tester“ ansteuert.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Verbindungspfade (gestrichelte rote Linien):</p>\n<ul class=\"fig-list\"><li>SOME/IP-Verbindungspfad zwischen ECU1 und ECU2 (Einspeisung gerichtet mit Pfeilspitze in „System Test Applications“).\n</li><li>DLT-Logging-Pfade von ECU1 und ECU2 über die jeweilige DLT-Komponente zum Jenkins-Host (beide Pfade enden gerichtet mit Pfeilspitzen am „LT Tester“).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>SOME/IP-Kommunikation</strong>: ECU1 sendet Datenströme (Video Data) über SOME/IP („vSomeIP“) via Ethernet an ECU2. Das Signal verläuft gerichtet von ECU1 über die Hardware-Verbindung zur ECU2, durchläuft den Stack aufwärts und wird in „System Test Applications“ eingespeist (Pfeilspitze an System Test Applications).\n</li><li><strong>Log-/Trace-Erfassung</strong>: Beide ECUs generieren Log- und Trace-Ereignisse über die DLT-Infrastruktur („Genivi-dlt“). Diese Nachrichten werden über separate Pfade an den Jenkins-Knoten übertragen und gerichtet an den „LT Tester“ übergeben (Pfeilspitzen am LT Tester für beide Ströme).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient als Referenzaufbau für Systemintegrationstests von Logging and Tracing. Es spezifiziert die Trennung von Teststimulus-/Nutzdatenkommunikation (SOME/IP zwischen den Test-ECUs) und Logging-Rückkanal (DLT zum Testrechner). Während für die ECUs weiterhin Linux mit Real-Time-Patches vorausgesetzt wird, genügt für den Jenkins-Host Standard-Linux.</p>"}, {"id": "FIG-eff710f4526b0392", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Block- und Deploymentdiagramm für den Testaufbau (Test Setup) zur Verifikation von Logging und Tracing (LT) in einer verteilten AUTOSAR Adaptive Platform Systemumgebung. Dargestellt ist die physische und logische Aufteilung auf zwei Steuergeräte (ECU1, ECU2) sowie einen externen Testautomatisierungsknoten (Jenkins).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das System umfasst drei Hauptknoten:</p>\n<ul class=\"fig-list\"><li><strong>ECU1</strong>: Hardware „Intel MinnowBoard“, Betriebssystem „Linux with Real-time Patches“. Software-Stack bestehend aus „POXIS libs (libc, ...)“, „vSomeIP“, „Ginivi-dlt“, „ARA“ sowie der Anwendung „LT Test Application(s)“.\n</li><li><strong>ECU2</strong>: Hardware „Renesas R-CAR H3 ULCB“, Betriebssystem „Linux with Real-time Patches“. Software-Stack bestehend aus „POXIS libs (libc, ...)“, „vSomeIP“, „Ginivi-dlt“, „ARA“ sowie der Anwendung „LT Test Application(s)“.\n</li><li><strong>Jenkins</strong>: Hardware „PC“, Betriebssystem „Linux“. Darauf läuft ein „Jenkins“-Block mit aufgesetztem „LT Tester“.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Verbindungspfade (gestrichelte rote Linien):</p>\n<ul class=\"fig-list\"><li>SOME/IP-Verbindungspfad zwischen ECU1 und ECU2 (gerichtet mit Pfeilspitze in „LT Test Application(s)“ auf ECU2).\n</li><li>DLT-Logging-Pfade von ECU1 und ECU2 über die jeweilige DLT-Komponente zum Jenkins-Host (beide gerichtet mit Pfeilspitzen am „LT Tester“).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>SOME/IP-Kommunikation</strong>: ECU1 sendet Test- und Nutzdaten über SOME/IP („vSomeIP“) via Ethernet an ECU2. Das Signal verläuft gerichtet von ECU1 über die Hardware-Verbindung zur ECU2, durchläuft den Stack aufwärts und wird in „LT Test Application(s)“ eingespeist (Pfeilspitze an LT Test Application(s)).\n</li><li><strong>Log-/Trace-Erfassung</strong>: Beide ECUs generieren Log- und Trace-Ereignisse über die DLT-Infrastruktur („Ginivi-dlt“) aus den jeweiligen „LT Test Application(s)“. Diese Nachrichten werden über separate Pfade an den Jenkins-Knoten übertragen und gerichtet an den „LT Tester“ übergeben (Pfeilspitzen am LT Tester für beide Ströme).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert den normativen Prüfaufbau für Systemtests des Logging and Tracing Subsystems. Beide Testknoten führen standardisierte „LT Test Application(s)“ aus, wodurch die Testsuite symmetrisch bzw. generisch für Logging- und Tracing-Validierungen eingesetzt werden kann, statt auf anwendungsspezifische Video-Streaming-Szenarien beschränkt zu sein.</p>"}, {"id": "FIG-b0fa294b89bd8353", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Block- und Deploymentdiagramm für den Testaufbau (Test Setup) zur Verifikation von Logging und Tracing (LT) in einer verteilten AUTOSAR Adaptive Platform Systemumgebung. Dargestellt ist die physische und logische Aufteilung auf zwei Steuergeräte (ECU1, ECU2) sowie einen externen Testautomatisierungsknoten (Jenkins).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das System umfasst drei Hauptknoten:</p>\n<ul class=\"fig-list\"><li><strong>ECU1</strong>: Hardware „Intel MinnowBoard“, Betriebssystem „Linux with Real-time Patches“. Software-Stack bestehend aus „POXIS libs (libc, ...)“, „vSomeIP“, „Ginivi-dlt“, „ARA“ sowie der Anwendung „LT Test Application(s)“.\n</li><li><strong>ECU2</strong>: Hardware „Renesas R-CAR H3 ULCB“, Betriebssystem „Linux with Real-time Patches“. Software-Stack bestehend aus „POXIS libs (libc, ...)“, „vSomeIP“, „Ginivi-dlt“, „ARA“ sowie der Anwendung „LT Test Application(s)“.\n</li><li><strong>Jenkins</strong>: Hardware „PC“, Betriebssystem „Linux“. Darauf läuft ein „Jenkins“-Block mit aufgesetztem „LT Tester“.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen und Verbindungspfade (gestrichelte rote Linien):</p>\n<ul class=\"fig-list\"><li>SOME/IP-Verbindungspfad zwischen ECU1 und ECU2 (gerichtet mit Pfeilspitze in „LT Test Application(s)“ auf ECU2).\n</li><li>DLT-Logging-Pfade von ECU1 und ECU2 über die jeweilige DLT-Komponente zum Jenkins-Host (beide gerichtet mit Pfeilspitzen am „LT Tester“).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\"><li><strong>SOME/IP-Kommunikation</strong>: ECU1 sendet Test- und Nutzdaten über SOME/IP („vSomeIP“) via Ethernet an ECU2. Das Signal verläuft gerichtet von ECU1 über die Hardware-Verbindung zur ECU2, durchläuft den Stack aufwärts und wird in „LT Test Application(s)“ eingespeist (Pfeilspitze an LT Test Application(s)).\n</li><li><strong>Log-/Trace-Erfassung</strong>: Beide ECUs generieren Log- und Trace-Ereignisse über die DLT-Infrastruktur („Ginivi-dlt“) aus den jeweiligen „LT Test Application(s)“. Diese Nachrichten werden über separate Pfade an den Jenkins-Knoten übertragen und gerichtet an den „LT Tester“ übergeben (Pfeilspitzen am LT Tester für beide Ströme).\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert den normativen Prüfaufbau für Systemtests des Logging and Tracing Subsystems. Beide Testknoten führen standardisierte „LT Test Application(s)“ aus, wodurch die Testsuite symmetrisch bzw. generisch für Logging- und Tracing-Validierungen eingesetzt werden kann, statt auf anwendungsspezifische Video-Streaming-Szenarien beschränkt zu sein.</p>"}], "trans": [{"from": "FIG-91b93f80faada818", "to": "FIG-c4f501c01aa30c48", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Typo-Korrektur in ECU1 und ECU2: „POSIX libs (libc, ...)“ war zuvor mit Tippfehler „POXIS libs (libc, ...)“ bzw. „Genivi-dlt“ wurde zu „Ginivi-dlt“ geändert.\n</li><li>Jenkins-Knoten: Betriebssystem-Ebene von „Linux with Real-time Patches“ auf „Linux“ verkürzt.\n</li><li>Am oberen Bildrand wurde versehentlich eine Textzeile aus dem Fließtext mitgerendert („connections on port 3490 and receives log messages from the LT module.“).\n</li></ul>"}, {"from": "FIG-c4f501c01aa30c48", "to": "FIG-eff710f4526b0392", "fr": "R19-03", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>ECU1: Anwendungsbaustein von „Video Data“ in „LT Test Application(s)“ umbenannt und standardisiert.\n</li><li>ECU2: Anwendungsbaustein von „System Test Applications“ in „LT Test Application(s)“ umbenannt.\n</li></ul>"}, {"from": "FIG-eff710f4526b0392", "to": "FIG-b0fa294b89bd8353", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
